<script setup lang="ts">
import type { StatisticsReport } from '~/types/statistics'
import { coverageMessage } from '~/utils/statistics'
import { displayDecimal, priceSources } from '~/utils/catalog'
import { formatCreatedAt } from '~/utils/material'
defineProps<{ value: StatisticsReport['observations']; zone: string }>()
</script>
<template>
  <section class="statistics-section" aria-labelledby="statistics-observations-title"><h2 id="statistics-observations-title">실사 소모와 판매별 배분</h2><p>{{ coverageMessage(value.coverage, '확인 수량') }}</p><p class="field-hint">기간 내 유효한 실사 정산을 품목·단위별로 합산합니다. 시작 기준·취소는 소모 합계에 넣지 않습니다.</p>
    <div v-if="value.summary_by_material.length" class="statistics-table-scroll" tabindex="0" role="region" aria-label="품목별 소모 합계 표"><table class="statistics-table"><caption>현재 품목명으로 보는 총소모 = 판매별 배분 + 미배분</caption><thead><tr><th scope="col">품목</th><th scope="col">총소모</th><th scope="col">판매별 배분</th><th scope="col">미배분</th></tr></thead><tbody><tr v-for="row in value.summary_by_material" :key="`${row.material_id}-${row.unit}`"><th scope="row"><NuxtLink :to="`/materials/${row.material_id}`">{{ row.material_name }}</NuxtLink><small>시작 {{ row.initial_records }} · 정산 {{ row.settlement_records }} · 취소 {{ row.void_records }}</small><details><summary>표시 이름 버전</summary><span class="material-id">{{ row.label_material_version_id }}</span></details></th><template v-if="row.settlement_records"><td>{{ displayDecimal(row.consumption_quantity) }}{{ row.unit }}<br>{{ displayDecimal(row.consumption_value) }}원</td><td>{{ displayDecimal(row.allocated_quantity) }}{{ row.unit }}<br>{{ displayDecimal(row.allocated_value) }}원</td><td>{{ displayDecimal(row.unallocated_quantity) }}{{ row.unit }}<br>{{ displayDecimal(row.unallocated_value) }}원<small v-if="row.no_sales_records">판매 없음 {{ row.no_sales_records }}건</small><small v-if="row.zero_weight_records">총개수 0 {{ row.zero_weight_records }}건</small></td></template><td v-else colspan="3">확정한 소모 없음 · 시작 기준과 취소를 0으로 계산하지 않습니다.</td></tr></tbody></table></div>
    <ol class="statistics-records"><li v-for="row in value.rows" :key="row.observation_id" :data-observation-id="row.observation_id"><details><summary>{{ row.material_name }} · {{ formatCreatedAt(row.origin.recorded_at, zone) }} · {{ row.status === 'void' ? '취소됨' : row.status === 'initial' ? '시작 기준' : '실사 정산' }}</summary><p class="field-hint">원관측 {{ row.position + 1 }}행 · 당시 품목명 {{ row.material_name }} · 단위 {{ row.unit }}</p><StatisticsReferences :origin="row.origin" :changes="row.changes" :zone="zone" />
        <p v-if="row.status === 'void'">취소된 확인 수량입니다. 이전 효과를 현재 소모로 합산하지 않습니다.</p><template v-else-if="row.effect"><p>현재 유효 확인 수량: {{ row.effect.material_name }} · {{ displayDecimal(row.effect.measured_quantity) }}{{ row.effect.unit }}</p><dl class="statistics-totals"><div><dt>확인 전 정산 기준</dt><dd>{{ row.effect.before ? `${displayDecimal(row.effect.before.quantity)}${row.effect.unit} · ${row.effect.before.value === null ? '가치 미확인' : displayDecimal(row.effect.before.value) + '원'}` : '시작 기준 없음' }}</dd></div><div><dt>확인 후 정산 기준</dt><dd>{{ displayDecimal(row.effect.after.quantity) }}{{ row.effect.unit }} · {{ row.effect.after.value === null ? '가치 미확인' : displayDecimal(row.effect.after.value) + '원' }}</dd></div><div v-if="row.effect.calculation.mode === 'initial'"><dt>시작 기준 가치</dt><dd>{{ displayDecimal(row.effect.calculation.value) }}원</dd></div><div v-else><dt>초과 조정 · 판매 소모와 별도</dt><dd>{{ displayDecimal(row.effect.calculation.excess_quantity) }}{{ row.effect.unit }} · {{ displayDecimal(row.effect.calculation.excess_value) }}원</dd></div></dl><p v-if="row.effect.calculation.valuation" class="field-hint">가치 출처: <template v-if="row.effect.calculation.valuation.kind === 'manual_amount'">직접 확인한 총금액 {{ displayDecimal(row.effect.calculation.valuation.amount) }}원</template><template v-else>{{ priceSources[row.effect.calculation.valuation.source] }} · {{ displayDecimal(row.effect.calculation.valuation.amount) }}원 / {{ displayDecimal(row.effect.calculation.valuation.quantity) }}{{ row.effect.unit }}</template></p><p v-if="row.status === 'initial'">시작 수량·가치의 기준입니다. 시작 이전 소모는 미확정이며 판매별 0을 만들지 않습니다.</p></template>
        <template v-if="row.status === 'settlement' && row.allocation"><dl class="statistics-totals"><div><dt>확정 소모</dt><dd>{{ displayDecimal(row.allocation.total_quantity) }}{{ row.effect?.unit ?? row.unit }} · {{ displayDecimal(row.allocation.total_value) }}원</dd></div><div><dt>미배분</dt><dd>{{ displayDecimal(row.allocation.unallocated_quantity) }}{{ row.effect?.unit ?? row.unit }} · {{ displayDecimal(row.allocation.unallocated_value) }}원</dd></div></dl><p v-if="row.allocation.reason === 'no_sales'">대상 판매가 없어 미배분으로 보존합니다.</p><p v-else-if="row.allocation.reason === 'zero_weight'">대상 판매 총개수가 0이라 판매별 수량·원가는 미배분입니다.</p><p class="field-hint">당시 레시피 사용량이 아닌 판매 개수 비율로 배분합니다. 기간 밖 판매도 원래 후보대로 유지합니다.</p><ul class="history-list"><li v-for="candidate in row.allocation.candidates" :key="`${candidate.sale_id}-${candidate.position}`"><NuxtLink :to="`/sales/${candidate.sale_id}`">판매 {{ candidate.sale_id.slice(0, 8) }}</NuxtLink><strong v-if="row.candidate_links.find(link => link.position === candidate.position)?.sale_in_period === false"> · 조회 기간 밖 판매</strong><p>{{ displayDecimal(candidate.count) }}개 · {{ candidate.quantity === null ? '수량 미배분' : displayDecimal(candidate.quantity) + (row.effect?.unit ?? row.unit) }} · {{ candidate.value === null ? '원가 미배분' : displayDecimal(candidate.value) + '원' }}</p></li></ul></template>
      </details></li></ol>
  </section>
</template>
